package com.hbm.block.oilplant;
import com.hbm.block.ore.LegacyOreBlock;import com.hbm.hazard.HbmHazards;import com.mojang.serialization.MapCodec;import java.util.*;import net.minecraft.core.*;import net.minecraft.core.registries.BuiltInRegistries;import net.minecraft.server.level.ServerLevel;import net.minecraft.util.RandomSource;import net.minecraft.world.entity.LivingEntity;import net.minecraft.world.entity.player.Player;import net.minecraft.world.item.ItemStack;import net.minecraft.world.item.context.BlockPlaceContext;import net.minecraft.world.level.*;import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.state.*;import net.minecraft.world.level.material.MapColor;import net.minecraft.world.level.storage.loot.LootParams;
/** Full source four tall stages, source cutting/regrowth, water/oily-soil uptake and mature harvest. */
public final class OilTallPlantBlock extends Block implements BonemealableBlock {
 public static final List<String> NAMES=List.of("weed","cd2","cd3","cd4");private static final ThreadLocal<Integer> GROWING=ThreadLocal.withInitial(()->0);private static final MapCodec<OilTallPlantBlock> CODEC=simpleCodec(p->new OilTallPlantBlock());
 public OilTallPlantBlock(){super(Properties.of().mapColor(MapColor.PLANT).strength(0).sound(SoundType.GRASS).noCollission().noOcclusion().randomTicks());registerDefaultState(stateDefinition.any().setValue(OilFlowerBlock.META,0));}@Override protected MapCodec<? extends Block> codec(){return CODEC;}@Override protected void createBlockStateDefinition(StateDefinition.Builder<Block,BlockState> builder){builder.add(OilFlowerBlock.META);}
 static void guard(Runnable action){int before=GROWING.get();GROWING.set(before+1);try{action.run();}finally{GROWING.set(before);}}
 public static void place(Level level,BlockPos pos,int meta){guard(()->{level.setBlock(pos,OilBotanyContent.TALL.get().defaultBlockState().setValue(OilFlowerBlock.META,meta),3);level.setBlock(pos.above(),OilBotanyContent.TALL.get().defaultBlockState().setValue(OilFlowerBlock.META,meta+8),3);});}
 @Override public BlockState getStateForPlacement(BlockPlaceContext context){var state=defaultBlockState().setValue(OilFlowerBlock.META,((OilPlantItem)context.getItemInHand().getItem()).metadata(context.getItemInHand()));return context.getLevel().isEmptyBlock(context.getClickedPos().above())&&canSurvive(state,context.getLevel(),context.getClickedPos())?state:null;}
 @Override public void setPlacedBy(Level level,BlockPos pos,BlockState state,LivingEntity placer,ItemStack stack){level.setBlock(pos.above(),defaultBlockState().setValue(OilFlowerBlock.META,state.getValue(OilFlowerBlock.META)+8),2);}
 @Override protected boolean canSurvive(BlockState state,LevelReader level,BlockPos pos){int meta=state.getValue(OilFlowerBlock.META);var below=level.getBlockState(pos.below());return meta>7?below.is(this)&&below.getValue(OilFlowerBlock.META)==meta-8:OilFlowerBlock.soil(below);}
 @Override protected void neighborChanged(BlockState state,Level level,BlockPos pos,Block block,BlockPos from,boolean moving){int meta=state.getValue(OilFlowerBlock.META);if(!canSurvive(state,level,pos)){if(meta<8)dropResources(state,level,pos);level.setBlock(pos,Blocks.AIR.defaultBlockState(),3);}if(GROWING.get()>0)return;var top=level.getBlockState(pos.above());if(meta<8&&(!top.is(this)||top.getValue(OilFlowerBlock.META)!=meta+8)&&OilFlowerBlock.soil(level.getBlockState(pos.below())))level.setBlock(pos,OilBotanyContent.FLOWER.get().defaultBlockState().setValue(OilFlowerBlock.META,meta==0?3:4),3);}
 @Override protected List<ItemStack> getDrops(BlockState state,LootParams.Builder params){int meta=state.getValue(OilFlowerBlock.META);var result=new ArrayList<ItemStack>();result.add(OilBotanyContent.flowerStack(meta%4==0?3:4));if(meta==11){var material=new ItemStack(OilBotanyContent.MATERIAL.get(),3+params.getLevel().random.nextInt(4));material.set(HbmHazards.LEGACY_METADATA.get(),2);result.add(material);}return result;}
 @Override public ItemStack getCloneItemStack(LevelReader level,BlockPos pos,BlockState state){var stack=new ItemStack(OilBotanyContent.TALL_ITEM.get());stack.set(HbmHazards.LEGACY_METADATA.get(),state.getValue(OilFlowerBlock.META)%8);return stack;}
 @Override public BlockState playerWillDestroy(Level level,BlockPos pos,BlockState state,Player player){if(!level.isClientSide&&state.getValue(OilFlowerBlock.META)<8&&level.getBlockState(pos.above()).is(this)){if(player.isCreative())level.setBlock(pos.above(),Blocks.AIR.defaultBlockState(),2);else dropResources(level.getBlockState(pos.above()),level,pos.above());}return super.playerWillDestroy(level,pos,state,player);}
 @Override protected void randomTick(BlockState state,ServerLevel level,BlockPos pos,RandomSource random){int meta=state.getValue(OilFlowerBlock.META);if(meta>7)return;if(meta%4==0&&OilFlowerBlock.oily(level.getBlockState(pos.below()))){level.setBlock(pos,BuiltInRegistries.BLOCK.get(net.minecraft.resources.ResourceLocation.parse("hbm:plant_dead")).defaultBlockState().setValue(LegacyOreBlock.LEGACY_META,3),3);return;}if(isValidBonemealTarget(level,pos,state)&&isBonemealSuccess(level,random,pos,state)&&random.nextInt(3)==0)performBonemeal(level,random,pos,state);}
 @Override public boolean isValidBonemealTarget(LevelReader level,BlockPos pos,BlockState state){int meta=state.getValue(OilFlowerBlock.META),rec=meta%4;BlockPos base=meta==rec?pos:pos.below();if((rec==1||rec==2)&&!OilFlowerBlock.water(level,base))return false;if(rec==2)return OilFlowerBlock.oily(level.getBlockState(base.below()));return rec!=3&&rec!=0;}
 @Override public boolean isBonemealSuccess(Level level,RandomSource random,BlockPos pos,BlockState state){return state.getValue(OilFlowerBlock.META)%4==2||random.nextFloat()<.33F;}
 @Override public void performBonemeal(ServerLevel level,RandomSource random,BlockPos pos,BlockState state){int meta=state.getValue(OilFlowerBlock.META),rec=meta%4;if(rec!=1&&rec!=2)return;guard(()->{if(meta==rec){level.setBlock(pos.above(),defaultBlockState().setValue(OilFlowerBlock.META,meta+9),3);level.setBlock(pos,defaultBlockState().setValue(OilFlowerBlock.META,meta+1),3);if(rec==2)level.setBlock(pos.below(),Blocks.DIRT.defaultBlockState(),3);}else{level.setBlock(pos,defaultBlockState().setValue(OilFlowerBlock.META,meta+1),3);level.setBlock(pos.below(),defaultBlockState().setValue(OilFlowerBlock.META,rec+1),3);if(rec==2)level.setBlock(pos.below(2),Blocks.DIRT.defaultBlockState(),3);}});}
}
